clear; clc; close all;

imageFiles = {'studded_tire.jpg', 'summer_tire.jpg'};


TIRE_THRESH   = 180;   
BRIGHT_THRESH = 140;   

for i = 1:numel(imageFiles) %[output:group:1ed77a73]
    % ---------- 1) Read & resize ----------
    fname = imageFiles{i};
    if ~isfile(fname)
        fname = strrep(fname, '.jpg', '.jpeg');
    end
    
    I = imread(fname);
    I = imresize(I, 0.5);   

    % ---------- 2) Convert to grayscale ----------
    if size(I, 3) == 3
        Igray = rgb2gray(I);
    else
        Igray = I;
    end
    
   
    IgraySmooth = imgaussfilt(Igray, 1.0);

    % ---------- 3) Create tire mask ----------
    tireMask = IgraySmooth < TIRE_THRESH;
    tireMask = imfill(tireMask, 'holes');
    tireMask = bwareaopen(tireMask, 500);
    tireMask = imerode(tireMask, strel('disk', 4));

    % ---------- 4) Candidate studs ----------
    cand = (IgraySmooth > BRIGHT_THRESH) & tireMask;
    cand = bwareaopen(cand, 3);
    cand = imfill(cand, 'holes');

    % ---------- 5) Connected components ----------
    CC = bwconncomp(cand);
    stats = regionprops(CC, 'Area', 'Perimeter', 'Eccentricity', 'PixelIdxList');

    % ---------- 6) Filter candidates ----------
    studMask = false(size(cand));
    studCount = 0;

    minA    = 4;     
    maxA    = 120;  
    minCirc = 0.6;   
    maxEcc  = 0.85;  

    for k = 1:numel(stats)
        A = stats(k).Area;
        P = stats(k).Perimeter;
        ecc = stats(k).Eccentricity;
        
        if P == 0
            continue;
        end
        
        circ = (4 * pi * A) / (P^2);
        
        if (A >= minA) && (A <= maxA) && (circ >= minCirc) && (ecc <= maxEcc)
            studCount = studCount + 1;
            studMask(stats(k).PixelIdxList) = true;
        end
    end

    % ---------- 7) Decision rule ----------
    tireArea = sum(tireMask(:));
    density = studCount / max(tireArea, 1);
    isStudded = (studCount > 10);

    % ---------- 8) Visualization ----------
    figure; %[output:3776b564] %[output:17be7eae]
    subplot(1,3,1); %[output:3776b564] %[output:17be7eae]
    imshow(I); title(sprintf('Input: %s', fname), 'Interpreter','none');
    
    subplot(1,3,2);
    imshow(cand); title('Candidate studs (binary)');
    
    subplot(1,3,3);
    imshow(I); hold on;
    visboundaries(studMask, 'LineWidth', 0.7);
    if isStudded
        title(sprintf('STUDDED TIRE (studs: %d)', studCount));
    else
        title(sprintf('NON-STUDDED TIRE (studs: %d)', studCount));
    end
end %[output:group:1ed77a73]

